"use strict";
const api = { name: "api", show() { console.log(this.name); } };
api.show();
const detached = api.show;
detached(); // undefined — lost implicit binding

function parse(raw) { return `${this.provider}:${raw}`; }
const lti = { provider: "lti" };
console.log(parse.call(lti, "jwt"));
const bound = parse.bind(lti);
console.log(bound("jwt"));

class Handler {
  handle() { return this.id; }
  handleArrow = () => this.id;
}
const h = new Handler();
h.id = "h1";
console.log(h.handle()); // h1
console.log(h.handleArrow()); // h1
console.log(h.handle()); // fails if detached: const f=h.handle; f()

const obj = {
  x: 10,
  getXLater() {
    setTimeout(function () { console.log(this.x); }, 0);
    setTimeout(() => console.log(this.x), 0);
  },
};
obj.getXLater(); // undefined then 10

class Btn {
  label = "save";
  onClick() { console.log(this.label); }
}
const b = new Btn();
document.addEventListener("click", b.onClick); // this is document or undefined
